import{_ as o,o as e,c as r,ah as s}from"./chunks/framework.DjU4PSOm.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["philosophy/Ethics"],"date":"2026-10-09T00:00:00.000Z"},"headers":[{"level":2,"title":"이 노트에 대하여","slug":"이-노트에-대하여","link":"#이-노트에-대하여","children":[]},{"level":2,"title":"1주차 (26-2 Ethics-Week-1.pdf)","slug":"_1주차-26-2-ethics-week-1-pdf","link":"#_1주차-26-2-ethics-week-1-pdf","children":[{"level":3,"title":"8쪽 — 도해: 윤리 vs 도덕 (두 층위의 구분)","slug":"_8쪽-—-도해-윤리-vs-도덕-두-층위의-구분","link":"#_8쪽-—-도해-윤리-vs-도덕-두-층위의-구분","children":[]},{"level":3,"title":"12쪽 — 도해: 윤리학의 핵심 물음들 (바퀴)","slug":"_12쪽-—-도해-윤리학의-핵심-물음들-바퀴","link":"#_12쪽-—-도해-윤리학의-핵심-물음들-바퀴","children":[]},{"level":3,"title":"15쪽 — 책 사진: Rachels, 『도덕철학의 기초(Elements of Moral Philosophy)』 1장 첫 부분","slug":"_15쪽-—-책-사진-rachels-『도덕철학의-기초-elements-of-moral-philosophy-』-1장-첫-부분","link":"#_15쪽-—-책-사진-rachels-『도덕철학의-기초-elements-of-moral-philosophy-』-1장-첫-부분","children":[]},{"level":3,"title":"17쪽 — 도해: 도덕의 최소 개념 (벤 다이어그램)","slug":"_17쪽-—-도해-도덕의-최소-개념-벤-다이어그램","link":"#_17쪽-—-도해-도덕의-최소-개념-벤-다이어그램","children":[]}]},{"level":2,"title":"2주차 (26-2 Ethics Week 2-Aristotle-Eudaimonia.pdf)","slug":"_2주차-26-2-ethics-week-2-aristotle-eudaimonia-pdf","link":"#_2주차-26-2-ethics-week-2-aristotle-eudaimonia-pdf","children":[{"level":3,"title":"8쪽 — 도해: 선의 세 단계 (삼각형)","slug":"_8쪽-—-도해-선의-세-단계-삼각형","link":"#_8쪽-—-도해-선의-세-단계-삼각형","children":[]},{"level":3,"title":"12쪽 — 책 사진: 『니코마코스 윤리학』 1권 7장, 1097a15–25 (Rowe 번역판 100쪽)","slug":"_12쪽-—-책-사진-『니코마코스-윤리학』-1권-7장-1097a15–25-rowe-번역판-100쪽","link":"#_12쪽-—-책-사진-『니코마코스-윤리학』-1권-7장-1097a15–25-rowe-번역판-100쪽","children":[]},{"level":3,"title":"14쪽 — 책 사진: 1권 7장, 1097a28–1097b21 (Rowe 번역판 101쪽)","slug":"_14쪽-—-책-사진-1권-7장-1097a28–1097b21-rowe-번역판-101쪽","link":"#_14쪽-—-책-사진-1권-7장-1097a28–1097b21-rowe-번역판-101쪽","children":[]}]},{"level":2,"title":"3주차 (26-2 Ethics-Week-3-Aristotles-Nicomachean-Ethics.pdf, 윤리학 3강.pdf)","slug":"_3주차-26-2-ethics-week-3-aristotles-nicomachean-ethics-pdf-윤리학-3강-pdf","link":"#_3주차-26-2-ethics-week-3-aristotles-nicomachean-ethics-pdf-윤리학-3강-pdf","children":[{"level":3,"title":"10쪽 — 책 사진: 『니코마코스 윤리학』 2권 1장, 1103a14–b25","slug":"_10쪽-—-책-사진-『니코마코스-윤리학』-2권-1장-1103a14–b25","link":"#_10쪽-—-책-사진-『니코마코스-윤리학』-2권-1장-1103a14–b25","children":[]},{"level":3,"title":"12쪽 — 도해: 본성과 습관화 사이의 아리스토텔레스의 입장","slug":"_12쪽-—-도해-본성과-습관화-사이의-아리스토텔레스의-입장","link":"#_12쪽-—-도해-본성과-습관화-사이의-아리스토텔레스의-입장","children":[]},{"level":3,"title":"18쪽 — 도해: 좋은 성품 ↔ 실천적 지혜 (벤 다이어그램)","slug":"_18쪽-—-도해-좋은-성품-↔-실천적-지혜-벤-다이어그램","link":"#_18쪽-—-도해-좋은-성품-↔-실천적-지혜-벤-다이어그램","children":[]}]},{"level":2,"title":"4주차 (26-2 Ethics-Week-4-Kants-Moral-Philosophy.pdf)","slug":"_4주차-26-2-ethics-week-4-kants-moral-philosophy-pdf","link":"#_4주차-26-2-ethics-week-4-kants-moral-philosophy-pdf","children":[{"level":3,"title":"6쪽 — 도해: 자연과학 vs 칸트 윤리","slug":"_6쪽-—-도해-자연과학-vs-칸트-윤리","link":"#_6쪽-—-도해-자연과학-vs-칸트-윤리","children":[]},{"level":3,"title":"23쪽 — 책 사진: 『도덕형이상학 정초』 제1절 첫 문단","slug":"_23쪽-—-책-사진-『도덕형이상학-정초』-제1절-첫-문단","link":"#_23쪽-—-책-사진-『도덕형이상학-정초』-제1절-첫-문단","children":[]}]},{"level":2,"title":"5주차 (26-2 윤리학 5강.pdf)","slug":"_5주차-26-2-윤리학-5강-pdf","link":"#_5주차-26-2-윤리학-5강-pdf","children":[{"level":3,"title":"18쪽 — 책 사진: 『도덕형이상학 정초』 제2절, Ak. 4:421 (정독 대상 쪽, 번역서 71쪽)","slug":"_18쪽-—-책-사진-『도덕형이상학-정초』-제2절-ak-4-421-정독-대상-쪽-번역서-71쪽","link":"#_18쪽-—-책-사진-『도덕형이상학-정초』-제2절-ak-4-421-정독-대상-쪽-번역서-71쪽","children":[]},{"level":3,"title":"27쪽 — 도해: 아리스토텔레스 ↔ 칸트 (서로를 교정함)","slug":"_27쪽-—-도해-아리스토텔레스-↔-칸트-서로를-교정함","link":"#_27쪽-—-도해-아리스토텔레스-↔-칸트-서로를-교정함","children":[]}]},{"level":2,"title":"6주차 (26-2 윤리학 6강.pdf)","slug":"_6주차-26-2-윤리학-6강-pdf","link":"#_6주차-26-2-윤리학-6강-pdf","children":[{"level":3,"title":"11쪽 — 책 사진: 제러미 벤담, 『도덕과 입법의 원리 서설』 제4장 (1823년판 29~30쪽)","slug":"_11쪽-—-책-사진-제러미-벤담-『도덕과-입법의-원리-서설』-제4장-1823년판-29-30쪽","link":"#_11쪽-—-책-사진-제러미-벤담-『도덕과-입법의-원리-서설』-제4장-1823년판-29-30쪽","children":[]}]},{"level":2,"title":"제외한 이미지","slug":"제외한-이미지","link":"#제외한-이미지","children":[]}],"relativePath":"philosophy/Ethics/13. 슬라이드 속 책 사진·도해 번역(1~6주차).md","filePath":"philosophy/Ethics/13. 슬라이드 속 책 사진·도해 번역(1~6주차).md"}'),l={name:"philosophy/Ethics/13. 슬라이드 속 책 사진·도해 번역(1~6주차).md"};function n(a,t,i,h,g,d){return e(),r("div",null,[...t[0]||(t[0]=[s('<blockquote><p>📎 <strong>슬라이드 위치</strong>: 1~6주차 슬라이드 PDF 전체 (책 사진 6곳 + 영어 도해 7곳). 장식용 일러스트 사진과 이미 한국어인 5강 카드는 제외.</p></blockquote><h2 id="이-노트에-대하여" tabindex="-1">이 노트에 대하여 <a class="header-anchor" href="#이-노트에-대하여" aria-label="Permalink to &quot;이 노트에 대하여&quot;">​</a></h2><p>슬라이드 안에 <strong>이미지로 들어가 있어서 텍스트로 복사되지 않는 내용</strong>(책 페이지 사진, 영어 도해)을 모아 한국어로 옮겼다. 슬라이드 쪽수 순서로 정리했다.</p><ul><li>아리스토텔레스·칸트·벤담의 원전은 공유 저작이지만 사진 속 영어판은 현대 번역본이라, 영어 문장을 그대로 옮기지 않고 <strong>원전의 논지를 따라 내 말로 번역</strong>했다.</li><li>교재(Rachels)는 현재 판매 중인 저작물이라 <strong>번역하지 않고 요지만 정리</strong>했다.</li><li>도해는 교수님 슬라이드의 짧은 라벨이라 그대로 옮겼다.</li><li>강의 해설은 각 주차 노트를 보면 된다: <a href="./01. 윤리학이란 무엇인가.html">01. 윤리학이란 무엇인가</a>, <a href="./02. 아리스토텔레스와 행복(에우다이모니아).html">02. 아리스토텔레스와 행복(에우다이모니아)</a>, <a href="./03. 목적의 완전성과 자족성(에우다이모니아의 형식적 조건).html">03. 목적의 완전성과 자족성(에우다이모니아의 형식적 조건)</a>, <a href="./04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치.html">04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치</a>, <a href="./07. 의무, 준칙, 선의지 정독(도덕형이상학 정초).html">07. 의무, 준칙, 선의지 정독(도덕형이상학 정초)</a>, <a href="./10. 정언명령, 보편법칙의 정식, 완전·불완전 의무.html">10. 정언명령, 보편법칙의 정식, 완전·불완전 의무</a>, <a href="./12. 벤담의 양적 공리주의(6주차 온라인).html">12. 벤담의 양적 공리주의(6주차 온라인)</a></li></ul><hr><h2 id="_1주차-26-2-ethics-week-1-pdf" tabindex="-1">1주차 (<code>26-2 Ethics-Week-1.pdf</code>) <a class="header-anchor" href="#_1주차-26-2-ethics-week-1-pdf" aria-label="Permalink to &quot;1주차 (`26-2 Ethics-Week-1.pdf`)&quot;">​</a></h2><h3 id="_8쪽-—-도해-윤리-vs-도덕-두-층위의-구분" tabindex="-1">8쪽 — 도해: 윤리 vs 도덕 (두 층위의 구분) <a class="header-anchor" href="#_8쪽-—-도해-윤리-vs-도덕-두-층위의-구분" aria-label="Permalink to &quot;8쪽 — 도해: 윤리 vs 도덕 (두 층위의 구분)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>1층위</th><th>2층위</th></tr></thead><tbody><tr><td><strong>도덕(Morality)</strong> (1차 수준) — 사람들이 실제로 따르는 <strong>규범, 관습, 가치, 판단</strong></td><td><strong>윤리(Ethics)</strong> (2차 수준) — 그 규범이 <strong>정당화되는지</strong>에 대한 철학적 성찰, 도덕에 대한 <strong>비판적 검토</strong></td></tr></tbody></table><h3 id="_12쪽-—-도해-윤리학의-핵심-물음들-바퀴" tabindex="-1">12쪽 — 도해: 윤리학의 핵심 물음들 (바퀴) <a class="header-anchor" href="#_12쪽-—-도해-윤리학의-핵심-물음들-바퀴" aria-label="Permalink to &quot;12쪽 — 도해: 윤리학의 핵심 물음들 (바퀴)&quot;">​</a></h3><p>가운데 &quot;<strong>윤리학의 핵심 물음들</strong>&quot;을 둘러싼 여섯 물음:</p><ol><li>나는 무엇을 해야 하는가? → <strong>행위</strong></li><li>나는 어떤 사람이 되어야 하는가? → <strong>성품</strong></li><li>나는 타인에게 무엇을 빚지고 있는가? → <strong>의무</strong></li><li>정의란 무엇인가? → <strong>제도</strong></li><li>도덕 판단은 참일 수 있는가? → <strong>메타윤리학</strong></li><li>우리는 AI를 어떻게 규제해야 하는가? → <strong>응용윤리학</strong></li></ol><p>아래쪽: &quot;윤리가 이끄는 것: 사고 · 결정 · 성품 · 사회 · 미래&quot;</p><h3 id="_15쪽-—-책-사진-rachels-『도덕철학의-기초-elements-of-moral-philosophy-』-1장-첫-부분" tabindex="-1">15쪽 — 책 사진: Rachels, 『도덕철학의 기초(Elements of Moral Philosophy)』 1장 첫 부분 <a class="header-anchor" href="#_15쪽-—-책-사진-rachels-『도덕철학의-기초-elements-of-moral-philosophy-』-1장-첫-부분" aria-label="Permalink to &quot;15쪽 — 책 사진: Rachels, 『도덕철학의 기초(Elements of Moral Philosophy)』 1장 첫 부분&quot;">​</a></h3><p>(번역하지 않고 요지만 정리 — 현재 판매 중인 교재)</p><ul><li>1장 제목은 &quot;도덕이란 무엇인가?&quot;이고, 제사로 소크라테스의 말(&quot;우리는 사소한 문제를 논의하는 것이 아니라 <strong>우리가 어떻게 살아야 하는가</strong>를 논의하고 있다&quot;, 플라톤 『국가』)을 든다.</li><li><strong>1.1절 &quot;정의의 문제&quot;</strong>: 도덕철학은 도덕이 무엇이고 우리에게 무엇을 요구하는지에 대한 탐구인데, 소크라테스의 넓은 정식을 넘어 구체적으로 정의하려 하면 경쟁하는 이론 중 하나와는 충돌하므로 모두가 받아들일 단일한 정의는 어렵다. 이것이 우리를 신중하게 하지만 판단을 마비시켜서는 안 되며, 저자는 모든 도덕 이론이 최소한 출발점으로 받아들여야 할 <strong>도덕의 최소 개념</strong>을 제시하겠다고 예고하고, 이를 위해 장애가 있는 아이들을 둘러싼 도덕적 논쟁 사례들을 먼저 살펴보겠다고 한다.</li></ul><h3 id="_17쪽-—-도해-도덕의-최소-개념-벤-다이어그램" tabindex="-1">17쪽 — 도해: 도덕의 최소 개념 (벤 다이어그램) <a class="header-anchor" href="#_17쪽-—-도해-도덕의-최소-개념-벤-다이어그램" aria-label="Permalink to &quot;17쪽 — 도해: 도덕의 최소 개념 (벤 다이어그램)&quot;">​</a></h3><ul><li>왼쪽 원 <strong>①</strong>: <strong>이성</strong>으로 행위를 이끌 것 — 단순한 감정이나 관습이 아니라</li><li>오른쪽 원 <strong>②</strong>: 영향받는 모든 개인의 <strong>이익을 동등하게 비중 있게</strong> 고려할 것</li><li>겹치는 부분: &quot;<strong>이 조건들은 모든 윤리 이론이 출발점으로 공유한다.</strong>&quot;</li></ul><hr><h2 id="_2주차-26-2-ethics-week-2-aristotle-eudaimonia-pdf" tabindex="-1">2주차 (<code>26-2 Ethics Week 2-Aristotle-Eudaimonia.pdf</code>) <a class="header-anchor" href="#_2주차-26-2-ethics-week-2-aristotle-eudaimonia-pdf" aria-label="Permalink to &quot;2주차 (`26-2 Ethics Week 2-Aristotle-Eudaimonia.pdf`)&quot;">​</a></h2><h3 id="_8쪽-—-도해-선의-세-단계-삼각형" tabindex="-1">8쪽 — 도해: 선의 세 단계 (삼각형) <a class="header-anchor" href="#_8쪽-—-도해-선의-세-단계-삼각형" aria-label="Permalink to &quot;8쪽 — 도해: 선의 세 단계 (삼각형)&quot;">​</a></h3><ul><li><strong>3단계 — 최고선</strong>(행복/에우다이모니아): <strong>언제나 그 자체를 위해</strong> 선택되고 그 너머의 어떤 것을 위해서도 선택되지 않는다.</li><li><strong>2단계</strong>: <strong>그 자체를 위해서도, 행복을 위해서도</strong> 선택되는 선들 (명예, 쾌락, 지성, 덕).</li><li><strong>1단계 — 도구적 선</strong>(돈, 도구, 자격): <strong>오직 다른 것을 위해서만</strong> 선택된다.</li></ul><h3 id="_12쪽-—-책-사진-『니코마코스-윤리학』-1권-7장-1097a15–25-rowe-번역판-100쪽" tabindex="-1">12쪽 — 책 사진: 『니코마코스 윤리학』 1권 7장, 1097a15–25 (Rowe 번역판 100쪽) <a class="header-anchor" href="#_12쪽-—-책-사진-『니코마코스-윤리학』-1권-7장-1097a15–25-rowe-번역판-100쪽" aria-label="Permalink to &quot;12쪽 — 책 사진: 『니코마코스 윤리학』 1권 7장, 1097a15–25 (Rowe 번역판 100쪽)&quot;">​</a></h3><blockquote><p>(1권 7장) 우리가 찾고 있는 그 <strong>선</strong>으로 돌아가 보자. 그것은 무엇일 수 있을까? 선은 활동이나 전문 영역마다 다른 것으로 보이기 때문이다. 의술에서 다르고 장군의 일에서 다르며 나머지도 그러하다. 그렇다면 각각에 속하는 선은 무엇인가? 그것은 나머지 모든 것이 <strong>그것을 위해</strong> 행해지는 바로 그것이 아닌가? 의술에서 그것은 건강이고, 장군의 일에서는 승리이며, 집짓기에서는 집이고, 다른 영역에서는 또 다른 어떤 것이다. 그러나 모든 활동과 기획에서 그것은 <strong>목적</strong>이다. 사람들은 이 목적을 위해 나머지를 모두 하기 때문이다. 따라서 모든 실천적 기획의 목적이 하나라면 그것이 <strong>실천 가능한 선</strong>이 될 것이고, 둘 이상이라면 그 여럿이 될 것이다. 이렇게 논증은 방향을 틀어 가며 <strong>같은 지점에 이르렀다.</strong> 그러나 이 문제에서는 훨씬 더 정밀하게 하려고 애써야 한다. 그런데 …</p></blockquote><p><em>(각주 2: 1097a25는 &quot;ἐπεὶ δή&quot;로 읽는다.)</em></p><h3 id="_14쪽-—-책-사진-1권-7장-1097a28–1097b21-rowe-번역판-101쪽" tabindex="-1">14쪽 — 책 사진: 1권 7장, 1097a28–1097b21 (Rowe 번역판 101쪽) <a class="header-anchor" href="#_14쪽-—-책-사진-1권-7장-1097a28–1097b21-rowe-번역판-101쪽" aria-label="Permalink to &quot;14쪽 — 책 사진: 1권 7장, 1097a28–1097b21 (Rowe 번역판 101쪽)&quot;">​</a></h3><blockquote><p>…목적이 분명히 하나 이상이고, 그 가운데 어떤 것들은 다른 것 때문에 선택한다면(부, 피리, 일반적으로 도구들이 그렇다), 모든 목적이 <strong>완전한</strong> 것은 아님이 분명하다. 그런데 최선은 분명 <strong>완전한</strong> 어떤 것이다. 그러므로 오직 하나만 완전하다면 그것이 우리가 찾는 것이고, 그런 것이 여럿이라면 그 가운데 <strong>가장 완전한</strong> 것이 그것이다.</p><p>이제 우리는 말한다: <strong>그 자체로 추구할 만한 것</strong>은 다른 것 때문에 추구할 만한 것보다 더 완전하고, <strong>다른 것 때문에는 결코 바랄 만하지 않은 것</strong>은 그 자체로도 바랄 만하고 그것 때문에도 바랄 만한 것들보다 더 완전하다. 그리고 <strong>무조건적으로 완전한 것</strong>은 언제나 그 자체로 바랄 만하고 결코 다른 것 때문에 바랄 만하지 않은 것이다.</p><p><strong>행복</strong>이 무엇보다 이와 같아 보인다. 우리는 행복을 언제나 그 자체 때문에 선택하고 결코 다른 것 때문에 선택하지 않지만, 명예, 쾌락, 지성, 그리고 모든 탁월함은 그 자체 때문에 선택하기도 하면서(아무 결과도 나오지 않는다 해도 우리는 그것들 각각을 선택할 것이므로) 그것들을 통해 행복해질 것이라 생각하여 <strong>행복을 위해서도</strong> 선택한다. 그러나 행복은 이것들을 위해, 또는 일반적으로 다른 어떤 것 때문에 선택하는 사람이 아무도 없다.</p><p><strong>자족성</strong>을 고려해도 같은 결론이 나오는 듯하다. 완전한 선은 자족적인 것으로 보이기 때문이다. 여기서 &#39;자족적&#39;이란 고립된 삶을 사는 사람 혼자에게 충분하다는 뜻이 아니라, 부모, 자녀, 아내, 일반적으로 사랑하는 사람들, 그리고 동료 시민에게도 충분하다는 뜻이다. 인간은 본성상 <strong>시민적 존재</strong>이기 때문이다. 다만 여기에는 한계가 있어야 한다. 이 논점을 조상과 후손, 그리고 사랑하는 이들의 사랑하는 이들에게까지 넓히면 <strong>무한한 계열</strong>이 생길 것이기 때문이다. 이 문제는 다른 기회에 살펴보아야 한다. 우리는 &#39;자족적&#39;이라는 것을, 그것만으로도 삶을 바랄 만하게 하고 <strong>아무것도 모자라지 않게 하는 것</strong>이라고 놓으며, 행복이 그런 것이라고 생각한다. 게다가 행복은 <strong>다른 선들과 함께 헤아려지지 않는, 모든 것 가운데 가장 바랄 만한 것</strong>이다. 만약 그렇게 헤아려진다면, 가장 작은 선 하나만 더해져도 우리는 그것을 더 바랄 만하다고 여길 것이 분명하다. 더해진 것은 선의 양을 늘리고, 선의 총량이 더 큰 것은 언제나 더 바랄 만하기 때문이다. 그러므로 행복은 분명 <strong>완전하고 자족적인 것</strong>이며 우리의 <strong>실천적 활동의 목적</strong>이다.</p></blockquote><hr><h2 id="_3주차-26-2-ethics-week-3-aristotles-nicomachean-ethics-pdf-윤리학-3강-pdf" tabindex="-1">3주차 (<code>26-2 Ethics-Week-3-Aristotles-Nicomachean-Ethics.pdf</code>, <code>윤리학 3강.pdf</code>) <a class="header-anchor" href="#_3주차-26-2-ethics-week-3-aristotles-nicomachean-ethics-pdf-윤리학-3강-pdf" aria-label="Permalink to &quot;3주차 (`26-2 Ethics-Week-3-Aristotles-Nicomachean-Ethics.pdf`, `윤리학 3강.pdf`)&quot;">​</a></h2><h3 id="_10쪽-—-책-사진-『니코마코스-윤리학』-2권-1장-1103a14–b25" tabindex="-1">10쪽 — 책 사진: 『니코마코스 윤리학』 2권 1장, 1103a14–b25 <a class="header-anchor" href="#_10쪽-—-책-사진-『니코마코스-윤리학』-2권-1장-1103a14–b25" aria-label="Permalink to &quot;10쪽 — 책 사진: 『니코마코스 윤리학』 2권 1장, 1103a14–b25&quot;">​</a></h3><p>이 사진의 번역은 <a href="./04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치.html">04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치</a> 맨 앞의 &quot;2권 1장 원문 번역&quot;에 이미 있다.</p><h3 id="_12쪽-—-도해-본성과-습관화-사이의-아리스토텔레스의-입장" tabindex="-1">12쪽 — 도해: 본성과 습관화 사이의 아리스토텔레스의 입장 <a class="header-anchor" href="#_12쪽-—-도해-본성과-습관화-사이의-아리스토텔레스의-입장" aria-label="Permalink to &quot;12쪽 — 도해: 본성과 습관화 사이의 아리스토텔레스의 입장&quot;">​</a></h3><ul><li><strong>극단 1</strong> — 사람은 덕스럽게 또는 악덕하게 <strong>태어난다</strong>(생물학적 결정론).</li><li><strong>극단 2</strong> — 윤리적 형성은 인간 본성과 <strong>전혀 맞지 않는다</strong>(백지설, 블랭크 슬레이트).</li><li><strong>아리스토텔레스의 입장</strong> — <strong>본성은 능력을 제공하고, 습관화가 그것을 완성한다.</strong></li></ul><h3 id="_18쪽-—-도해-좋은-성품-↔-실천적-지혜-벤-다이어그램" tabindex="-1">18쪽 — 도해: 좋은 성품 ↔ 실천적 지혜 (벤 다이어그램) <a class="header-anchor" href="#_18쪽-—-도해-좋은-성품-↔-실천적-지혜-벤-다이어그램" aria-label="Permalink to &quot;18쪽 — 도해: 좋은 성품 ↔ 실천적 지혜 (벤 다이어그램)&quot;">​</a></h3><ul><li>왼쪽: <strong>좋은 성품</strong> — 욕구를 가치 있는 목적으로 이끈다.</li><li>오른쪽: <strong>실천적 지혜(프로네시스)</strong> — 주어진 상황에서 알맞은 행위를 식별한다.</li><li>겹침: <strong>상호 의존</strong></li><li>아래 두 상자: &quot;좋은 성품이 없으면 <strong>지성은 나쁜 목적에 봉사한다.</strong>&quot; / &quot;실천적 지혜가 없으면 <strong>좋은 의도도 해를 낳는다.</strong>&quot;</li></ul><hr><h2 id="_4주차-26-2-ethics-week-4-kants-moral-philosophy-pdf" tabindex="-1">4주차 (<code>26-2 Ethics-Week-4-Kants-Moral-Philosophy.pdf</code>) <a class="header-anchor" href="#_4주차-26-2-ethics-week-4-kants-moral-philosophy-pdf" aria-label="Permalink to &quot;4주차 (`26-2 Ethics-Week-4-Kants-Moral-Philosophy.pdf`)&quot;">​</a></h2><h3 id="_6쪽-—-도해-자연과학-vs-칸트-윤리" tabindex="-1">6쪽 — 도해: 자연과학 vs 칸트 윤리 <a class="header-anchor" href="#_6쪽-—-도해-자연과학-vs-칸트-윤리" aria-label="Permalink to &quot;6쪽 — 도해: 자연과학 vs 칸트 윤리&quot;">​</a></h3><table tabindex="0"><thead><tr><th>자연과학</th><th>칸트 윤리</th></tr></thead><tbody><tr><td><strong>자연의 법칙</strong>을 가진다</td><td><strong>자유의 법칙</strong>을 가진다</td></tr><tr><td>무슨 일이 <strong>일어나는지</strong>를 기술한다</td><td>무슨 일이 <strong>일어나야 하는지</strong>를 규정한다</td></tr><tr><td><strong>인과적 필연성</strong></td><td><strong>실천적 필연성</strong></td></tr><tr><td>대상은 <strong>선택하지 않는다</strong></td><td>이성적 행위자는 <strong>원리에 따라</strong> 행위한다</td></tr></tbody></table><h3 id="_23쪽-—-책-사진-『도덕형이상학-정초』-제1절-첫-문단" tabindex="-1">23쪽 — 책 사진: 『도덕형이상학 정초』 제1절 첫 문단 <a class="header-anchor" href="#_23쪽-—-책-사진-『도덕형이상학-정초』-제1절-첫-문단" aria-label="Permalink to &quot;23쪽 — 책 사진: 『도덕형이상학 정초』 제1절 첫 문단&quot;">​</a></h3><p>번역은 <a href="./07. 의무, 준칙, 선의지 정독(도덕형이상학 정초).html">07. 의무, 준칙, 선의지 정독(도덕형이상학 정초)</a>의 &quot;원문 번역&quot; 절에 있다.</p><hr><h2 id="_5주차-26-2-윤리학-5강-pdf" tabindex="-1">5주차 (<code>26-2 윤리학 5강.pdf</code>) <a class="header-anchor" href="#_5주차-26-2-윤리학-5강-pdf" aria-label="Permalink to &quot;5주차 (`26-2 윤리학 5강.pdf`)&quot;">​</a></h2><h3 id="_18쪽-—-책-사진-『도덕형이상학-정초』-제2절-ak-4-421-정독-대상-쪽-번역서-71쪽" tabindex="-1">18쪽 — 책 사진: 『도덕형이상학 정초』 제2절, Ak. 4:421 (정독 대상 쪽, 번역서 71쪽) <a class="header-anchor" href="#_18쪽-—-책-사진-『도덕형이상학-정초』-제2절-ak-4-421-정독-대상-쪽-번역서-71쪽" aria-label="Permalink to &quot;18쪽 — 책 사진: 『도덕형이상학 정초』 제2절, Ak. 4:421 (정독 대상 쪽, 번역서 71쪽)&quot;">​</a></h3><p>(사진 맨 윗줄은 잘려 있다: &quot;…필연적인 것으로 제시하는 …&quot;)</p><blockquote><p>그러므로 정언명령은 <strong>오직 하나뿐</strong>이며, 그것은 이렇다. <strong>네가 동시에 그 준칙이 보편법칙이 되기를 의지할 수 있는 바로 그 준칙에 따라서만 행위하라.</strong></p><p>이제 의무의 모든 명령이 이 하나의 명령에서 그 원리로부터인 듯 도출될 수 있다면, 비록 의무라 불리는 것이 애초에 <strong>공허한 개념</strong>이 아닌지는 미결로 남겨 두더라도, 우리는 적어도 우리가 그것으로 무엇을 생각하는지, 그리고 그 개념이 무엇을 뜻하는지는 <strong>제시할 수 있을 것이다.</strong></p><p>결과가 일어나는 법칙의 보편성이, 가장 일반적인 의미에서(형식에 따라) 실제로 <strong>자연</strong>이라 불리는 것, 곧 보편적 법칙에 의해 규정되는 한에서의 사물들의 존재를 이루므로, 의무의 보편적 명령은 이렇게도 표현될 수 있다. <strong>마치 네 행위의 준칙이 네 의지에 의해 보편적 자연법칙이 되어야 하는 것처럼 행위하라.</strong></p><p>이제 우리는 의무들을 통상적인 구분에 따라, <strong>자기 자신에 대한 의무와 다른 인간에 대한 의무</strong>로, 그리고 <strong>완전의무와 불완전의무</strong>로 나누어 열거해 보겠다.*</p></blockquote><p>(별표(*)는 칸트의 각주 표시. 이 대목의 문장별 해설은 <a href="./10. 정언명령, 보편법칙의 정식, 완전·불완전 의무.html">10. 정언명령, 보편법칙의 정식, 완전·불완전 의무</a>의 &quot;『정초』 2절 정독&quot; 참고.)</p><h3 id="_27쪽-—-도해-아리스토텔레스-↔-칸트-서로를-교정함" tabindex="-1">27쪽 — 도해: 아리스토텔레스 ↔ 칸트 (서로를 교정함) <a class="header-anchor" href="#_27쪽-—-도해-아리스토텔레스-↔-칸트-서로를-교정함" aria-label="Permalink to &quot;27쪽 — 도해: 아리스토텔레스 ↔ 칸트 (서로를 교정함)&quot;">​</a></h3><p>이 도해는 이미 한국어다. 왼쪽 <strong>아리스토텔레스</strong>: 품성(성격) · 습관 형성 · 감정 · 실천적 지혜(프로네시스) · 인간의 번영(행복한 삶) · 구체적 상황에 대한 지각. 오른쪽 <strong>칸트</strong>: 보편 법칙 · 이성적 일관성 · 의무 · 자율성 · 정언 명령의 검증 · 모든 인간의 도덕적 평등한 지위. 가운데: &quot;서로의 맹점을 교정해 줌&quot;.</p><hr><h2 id="_6주차-26-2-윤리학-6강-pdf" tabindex="-1">6주차 (<code>26-2 윤리학 6강.pdf</code>) <a class="header-anchor" href="#_6주차-26-2-윤리학-6강-pdf" aria-label="Permalink to &quot;6주차 (`26-2 윤리학 6강.pdf`)&quot;">​</a></h2><h3 id="_11쪽-—-책-사진-제러미-벤담-『도덕과-입법의-원리-서설』-제4장-1823년판-29-30쪽" tabindex="-1">11쪽 — 책 사진: 제러미 벤담, 『도덕과 입법의 원리 서설』 제4장 (1823년판 29~30쪽) <a class="header-anchor" href="#_11쪽-—-책-사진-제러미-벤담-『도덕과-입법의-원리-서설』-제4장-1823년판-29-30쪽" aria-label="Permalink to &quot;11쪽 — 책 사진: 제러미 벤담, 『도덕과 입법의 원리 서설』 제4장 (1823년판 29~30쪽)&quot;">​</a></h3><blockquote><p><strong>제4장 — 쾌락 또는 고통의 가치, 그 측정 방법</strong></p><p><strong>I.</strong> 쾌락과 고통의 회피는 입법자가 염두에 두는 <strong>목적</strong>이다. 그러므로 입법자는 그 <strong>가치</strong>를 이해해야 한다. 쾌락과 고통은 그가 다루어야 하는 <strong>도구</strong>이다. 그러므로 그는 그 힘, 곧 다른 말로 그 가치를 이해해야 한다. <em>(여백 요약: 이 장의 용도)</em></p><p><strong>II.</strong> <strong>한 사람 자신</strong>에게서, <strong>쾌락이나 고통 그 자체</strong>의 가치는 다음 네 가지 사정에 따라 더 크거나 작아진다.¹<br> ① 그 <strong>강도</strong>.<br> ② 그 <strong>지속성</strong>.<br> ③ 그 <strong>확실성</strong> 또는 불확실성.<br> ④ 그 <strong>근접성</strong> 또는 원격성.<br><em>(여백 요약: 단일 인물에 관해, 쾌락·고통 그 자체의 가치를 평가할 때 고려할 사정)</em></p><p><strong>III.</strong> 이것들은 쾌락이나 고통을 <em>각각 그 자체로</em> 평가할 때 고려해야 할 사정이다. 그러나 어떤 쾌락이나 고통의 가치를, 그것을 낳는 어떤 <strong>행위</strong>의 경향을 평가하기 위해 고려할 때에는 두 가지 다른 사정이 더 고려되어야 한다. 그것은 다음과 같다. <em>(여백 요약: 다른 쾌락·고통과 연관시켜 고려할 때)</em></p><p>¹ 이 사정들은 이후 쾌락·고통의 가치의 <strong>요소</strong> 또는 <strong>차원</strong>이라 불려 왔다.<br> 초판이 나오고 얼마 지나지 않아, 도덕과 입법의 전 구조가 의존하는 이 요점들을 기억에 더 잘 새기기 위해 다음의 기억용 시구가 지어졌다.</p><p><em>강렬하고, 길고, 확실하고, 빠르고, 다산적이고, 순수한 —</em><br><em>쾌락과 고통에서 이런 표지들은 오래 남는다.</em><br><em>이런 쾌락은 구하라, 네 목적이 <strong>사적</strong>이라면.</em><br><em>그것이 <strong>공적</strong>이라면, 널리 퍼지게 하라.</em><br><em>이런 고통은 피하라, 네 관점이 무엇이든.</em><br><em>고통이 <strong>꼭 와야</strong> 한다면, 소수에게만 미치게 하라.</em></p></blockquote><p><strong>제4장 계속 (30쪽)</strong></p><blockquote><p>⑤ 그 <strong>다산성</strong>, 곧 같은 종류의 감각이 뒤따를 가능성. 즉 쾌락이면 쾌락이, 고통이면 고통이 뒤따르는 것.<br> ⑥ 그 <strong>순수성</strong>, 곧 반대 종류의 감각이 뒤따르지 <strong>않을</strong> 가능성. 즉 쾌락이면 고통이, 고통이면 쾌락이 뒤따르지 않는 것.</p><p>그러나 이 마지막 두 가지는 엄밀히 말해 <strong>쾌락이나 고통 그 자체의 속성</strong>으로 보기 어렵다. 그것들은 엄밀히는 그러한 쾌락이나 고통을 낳은 <strong>행위나 다른 사건의 속성</strong>으로만 간주되어야 하며, 따라서 그런 행위의 <strong>경향</strong>을 평가할 때에만 고려된다.</p></blockquote><p>(강의 해설: <a href="./12. 벤담의 양적 공리주의(6주차 온라인).html">12. 벤담의 양적 공리주의(6주차 온라인)</a>의 &quot;정독&quot; 절. 7번째 차원인 <strong>범위(extent)</strong> 는 이 쪽 다음에 나오는 항목이다.)</p><hr><h2 id="제외한-이미지" tabindex="-1">제외한 이미지 <a class="header-anchor" href="#제외한-이미지" aria-label="Permalink to &quot;제외한 이미지&quot;">​</a></h2><ul><li>표지·분위기용 <strong>일러스트/사진</strong>(원기둥 신전, 도서관, 활 쏘는 사람, 교실, 촛불, 칸트·벤담 초상화, 돼지 사진 등)과 아이콘만 있는 도해는 글자가 없어 번역할 내용이 없다.</li><li>6강 17쪽의 <strong>돼지 사진</strong>은 벤담의 &quot;고통을 느낄 수 있는가&quot; 논점(동물 윤리)을 가리키는 그림이다 → <a href="./12. 벤담의 양적 공리주의(6주차 온라인).html">12. 벤담의 양적 공리주의(6주차 온라인)</a>.</li><li>5강 13·20·24·28·29쪽의 분홍 카드는 이미 한국어 텍스트다.</li></ul>',58)])])}const u=o(l,[["render",n]]);export{p as __pageData,u as default};
